previewCss:
.darma-loader-darma-b16-bunsen-burner { --accent: var(--loader-color, #2563eb); --accent-2: var(--loader-secondary-color, #a5f3fc); width: var(--loader-size, 108px); height: var(--loader-size, 108px); position: relative; }
.darma-loader-darma-b16-bunsen-burner .darma-loader-darma-b16-bunsen-burner__foot { position: absolute; left: 24%; right: 24%; bottom: 4%; height: 9%; border-radius: 4px 4px 6px 6px; background: linear-gradient(#94a3b8, #334155); }
.darma-loader-darma-b16-bunsen-burner .darma-loader-darma-b16-bunsen-burner__barrel { position: absolute; left: 42%; bottom: 12%; width: 16%; height: 34%; border-radius: 3px; background: linear-gradient(90deg, #cbd5e1, #64748b); }
.darma-loader-darma-b16-bunsen-burner .darma-loader-darma-b16-bunsen-burner__barrel::after { content: ''; position: absolute; left: -30%; bottom: 8%; width: 160%; height: 16%; border-radius: 3px; background: #475569; }
.darma-loader-darma-b16-bunsen-burner .darma-loader-darma-b16-bunsen-burner__flame { position: absolute; left: 38%; bottom: 44%; width: 24%; height: 44%; border-radius: 50% 50% 42% 42% / 76% 76% 24% 24%; background: linear-gradient(color-mix(in srgb, #fff 40%, var(--accent-2)), var(--accent)); filter: blur(1px); transform-origin: 50% 100%; animation: darma-loader-darma-b16-bunsen-burner-bunsen-lick calc(var(--loader-speed, 1s) * .7) ease-in-out infinite alternate; }
.darma-loader-darma-b16-bunsen-burner .darma-loader-darma-b16-bunsen-burner__inner { position: absolute; left: 44%; bottom: 46%; width: 12%; height: 22%; border-radius: 50% 50% 40% 40% / 76% 76% 24% 24%; background: color-mix(in srgb, #fff 55%, var(--accent-2)); transform-origin: 50% 100%; animation: darma-loader-darma-b16-bunsen-burner-bunsen-core calc(var(--loader-speed, 1s) * .7) ease-in-out infinite alternate; }
@keyframes darma-loader-darma-b16-bunsen-burner-bunsen-lick { from { transform: scaleY(.86) scaleX(1.06) skewX(-3deg); opacity: .85; } to { transform: scaleY(1.12) scaleX(.94) skewX(3deg); opacity: 1; } }
@keyframes darma-loader-darma-b16-bunsen-burner-bunsen-core { from { transform: scaleY(.8); } to { transform: scaleY(1.15); } }

